// Task intake guard: Origin allow-list + size limits. No content is logged or stored.
// Optional "prefill" (from an "Ask for me" button on a provider page / guide):
//   { task_type, organisation: { name, phone, category, resource_id }, goal_hint }
// Optional "hint_task_type" (example chip in the UI): soft hint only.
const ALLOWED_ORIGINS = [
  /^http:\/\/localhost:8787$/,
  /^http:\/\/127\.0\.0\.1:8787$/,
  /^https:\/\/[a-z0-9-]+(\.[a-z0-9-]+)*\.lovable\.app$/,
  /^https:\/\/[a-z0-9-]+(\.[a-z0-9-]+)*\.lovableproject\.com$/
];
const LANGS = ['en','ar','tr','uk','ru','fa','prs','hi','es','fr','pl','vi','zh','de'];
const TYPES = ['doctor_appointment','authority_appointment','landlord_request','contract_question','bank_enquiry','pharmacy_question','restaurant_booking','other_call','course_enquiry','kita_enquiry'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const MAX_TEXT = 600;
const str = (v, n) => (typeof v === 'string' || typeof v === 'number') ? String(v).trim().slice(0, n) : '';

const h = $json.headers || {};
const origin = String(h.origin || h.Origin || '').trim().toLowerCase();
const b = (typeof $json.body === 'object' && $json.body) ? $json.body : {};

const fail = (status, error) => ({ json: { ok: false, status, error } });

if (!origin || !ALLOWED_ORIGINS.some(re => re.test(origin))) return fail(403, 'origin_not_allowed');

const text = typeof b.text === 'string' ? b.text.trim() : '';
if (text.length > MAX_TEXT) return fail(413, 'text_too_long');

let draft = null;
if (b.draft != null) {
  if (typeof b.draft !== 'object' || Array.isArray(b.draft)) return fail(400, 'draft_invalid');
  if (JSON.stringify(b.draft).length > 5000) return fail(413, 'draft_too_large');
  draft = b.draft;
}
let prefill = null;
if (b.prefill != null) {
  const p = b.prefill;
  if (typeof p !== 'object' || Array.isArray(p)) return fail(400, 'prefill_invalid');
  if (JSON.stringify(p).length > 1500) return fail(413, 'prefill_too_large');
  const o = (p.organisation && typeof p.organisation === 'object' && !Array.isArray(p.organisation)) ? p.organisation : {};
  const rid = str(o.resource_id, 40);
  prefill = {
    task_type: TYPES.includes(p.task_type) ? p.task_type : null,
    organisation: { name: str(o.name, 120), phone: str(o.phone, 30), category: str(o.category, 40), resource_id: UUID.test(rid) ? rid.toLowerCase() : null },
    goal_hint: str(p.goal_hint, 200)
  };
}
if (!text && !draft && !prefill) return fail(400, 'text_required');

let answers = null;
if (b.answers != null) {
  const a = Array.isArray(b.answers) ? b.answers : (typeof b.answers === 'object' ? Object.entries(b.answers).map(([field, answer]) => ({ field, answer })) : null);
  if (!a || a.length > 10) return fail(400, 'answers_invalid');
  answers = a.map(x => ({ field: String(x.field ?? '').slice(0, 60), answer: String(x.answer ?? x.value ?? '').slice(0, 200) }));
}
const round = Number.isInteger(b.round) ? b.round : (draft ? 2 : 1);
if (round > 5) return fail(429, 'too_many_rounds');

const uiLang = LANGS.includes(b.ui_lang) ? b.ui_lang : (LANGS.includes(b.ui_language) ? b.ui_language : 'en');
const hintType = TYPES.includes(b.hint_task_type) ? b.hint_task_type : null;
return { json: { ok: true, status: 200, origin, text, ui_lang: uiLang, draft, answers, round, prefill, hint_task_type: hintType } };

