// Validate + clean the Claude draft (server-side guarantees; never trust the model blindly).
// ESSENTIALS per task type (Plan v2 D2). To add a task type: add it here, in the schema enum
// of "Task Draft Schema", in workflow 01 TASK_TEMPLATES and in the DB check constraint.
// 'fact:a|b' = one allowed_fact whose key contains a or b.
// PREFILL ("Ask for me" on a provider page): organisation + resource_id from prefill always win.
const ESSENTIALS = {
  doctor_appointment:    ['organisation.phone', 'person.name', 'reason_category', 'is_new_patient', 'insurance_type', 'time_windows'],
  authority_appointment: ['organisation.phone', 'person.name', 'goal_user', 'time_windows'],
  landlord_request:      ['organisation.phone', 'person.name', 'fact:address', 'goal_user', 'time_windows'],
  contract_question:     ['organisation.phone', 'person.name', 'fact:contract_type'],
  bank_enquiry:          ['organisation.phone', 'person.name', 'goal_user'],
  pharmacy_question:     ['organisation.phone', 'person.name', 'fact:medicine'],
  restaurant_booking:    ['organisation.phone', 'person.name', 'time_windows', 'constraints.party_size'],
  other_call:            ['organisation.phone', 'person.name', 'goal_user'],
  course_enquiry:        ['organisation.phone', 'person.name', 'fact:child_age', 'goal_user'],
  kita_enquiry:          ['organisation.phone', 'person.name', 'fact:child_age|child_birth', 'fact:start_month']
};
const TYPES = Object.keys(ESSENTIALS);
const LANGS = ['en','ar','tr','uk','ru','fa','prs','hi','es','fr','pl','vi','zh','de'];
const REASONS = ['first_visit','checkup','acute','follow_up','specialist','other'];
const REFUSE = ['emergency','not_by_phone','unsafe'];
const HEALTH_RE = /(?<!\p{L})(?:(?:schmerz|kopfschmerz|bauchschmerz|fieber|husten|übelkeit|erbrechen|durchfall|ausschlag|schwanger|depressi|angststörung|diabet|krebs|infektion|entzündung|allergi|asthma|blutung|migräne|grippe|symptom|diagnos|autis|epilep|neurodermitis|behinder|headache|nausea|vomit|diarrh|pregnan|depress|anxiety|cancer|infection|inflammation|allerg|bleeding|migraine|fever|cough|painful|disab|ağrı|ateş|öksürük|hamile|astım|alerji|hastalı|otizm|diyabet|engelli|біль(?!ш)|боль(?!ш)|болит|болезн|болеет|болен|хвор|кашель|астм|аллерг|алерг|аутизм|епілеп|эпилеп|діабет|диабет|инвалид|інвалід)\p{L}*|(?:flu|rash|pain|sick|krank|krankheit|adhs|adhd|сдвг|сдуг)(?!\p{L}))/giu;
const HEALTH_RE_AR = /(ألم(?!ان)|آلام|حمى|سعال|حامل|سرطان|اكتئاب|إسهال|صداع|حساسية|مرض|مريض|(?<!\p{L})[وبلف]?(?:ال)?(?:ربو|سكري|صرع|توحد)(?!\p{L}))/gu;
const strip = s => String(s ?? '').replace(HEALTH_RE, '').replace(HEALTH_RE_AR, '').replace(/\s{2,}/g, ' ').replace(/\s+([,.;:!?])/g, '$1').trim();
const hasHealth = s => { HEALTH_RE.lastIndex = 0; HEALTH_RE_AR.lastIndex = 0; return HEALTH_RE.test(String(s ?? '')) || HEALTH_RE_AR.test(String(s ?? '')); };
const str = (v, n) => (v == null ? '' : String(v)).trim().slice(0, n);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const normPhone = v => { let p = str(v, 30).replace(/[\s\/\-()]/g, ''); if (p.startsWith('0049')) p = '+49' + p.slice(4); return /^(\+49|0)\d{6,14}$/.test(p) ? p : ''; };

const d = $json.output ?? $json;
const input = $('Check Origin + Size').item.json;
const pre = input.prefill || null;
const preOrg = pre?.organisation || {};
const prevOrg = (input.draft && typeof input.draft.organisation === 'object' && input.draft.organisation) || {};
const taskType = (pre?.task_type && TYPES.includes(pre.task_type)) ? pre.task_type : (TYPES.includes(d.task_type) ? d.task_type : 'other_call');
const userLang = LANGS.includes(d.user_language) ? d.user_language : input.ui_lang;
const isPharmacy = taskType === 'pharmacy_question';
let sensitive = d.sensitive_removed === true;

// phone: strip spaces, '/', '-', '(', ')' then validate German format; a valid prefill phone wins
const phone = normPhone(preOrg.phone) || normPhone(d.organisation?.phone);
const orgName = str(preOrg.name, 120) || str(d.organisation?.name, 120);
const orgCategory = str(preOrg.category, 40) || str(d.organisation?.category, 40) || (taskType === 'course_enquiry' ? 'course' : taskType === 'kita_enquiry' ? 'kita' : '');
const ridCand = [preOrg.resource_id, prevOrg.resource_id, input.draft?.resource_id].map(v => str(v, 40)).find(v => UUID.test(v));
const resourceId = ridCand ? ridCand.toLowerCase() : null;

let goalUser = str(d.goal_user, 200);
let goalDe = str(d.goal_de, 300);
// goals never carry health details (medicine names are allowed only as a pharmacy fact)
if (hasHealth(goalUser)) { goalUser = strip(goalUser); sensitive = true; }
if (hasHealth(goalDe)) { goalDe = strip(goalDe); sensitive = true; }

const today = $now.setZone('Europe/Berlin').startOf('day');
// a draft that asks for time_windows while also returning some has invented them -> drop them
const asksWindows = (Array.isArray(d.missing) ? d.missing : []).some(m => /time_window|zeitfenster/i.test(String(m?.field ?? '')));
const windows = (asksWindows ? [] : Array.isArray(d.time_windows) ? d.time_windows : [])
  .filter(w => w && /^\d{4}-\d{2}-\d{2}$/.test(w.date) && /^\d{2}:\d{2}$/.test(w.from) && /^\d{2}:\d{2}$/.test(w.to) && w.from < w.to)
  .filter(w => { const dt = DateTime.fromISO(w.date, { zone: 'Europe/Berlin' }); return dt >= today && dt <= today.plus({ days: 60 }); })
  .slice(0, 3)
  .map(w => ({ date: w.date, from: w.from, to: w.to }));

// DEF-050: we never collect a child's name (GDPR data minimisation): no child-name fact, note or question.
const CHILD_NAME = /child.*name/i;
const childNames = (Array.isArray(d.allowed_facts) ? d.allowed_facts : []).filter(f => CHILD_NAME.test(str(f?.key, 40))).map(f => str(f?.value, 80).toLowerCase()).filter(v => v.length > 1);
const c = d.constraints || {};
const constraints = {};
if (Number.isFinite(c.budget_max_eur) && c.budget_max_eur > 0) constraints.budget_max_eur = c.budget_max_eur;
if (Number.isInteger(c.party_size) && c.party_size > 0 && c.party_size <= 30) constraints.party_size = c.party_size;
if (str(c.deadline, 40)) constraints.deadline = str(c.deadline, 40);
if (str(c.notes_de, 200) && !hasHealth(c.notes_de) && !childNames.some(v => str(c.notes_de, 200).toLowerCase().includes(v))) constraints.notes_de = str(c.notes_de, 200);

const facts = [];
for (const f of (Array.isArray(d.allowed_facts) ? d.allowed_facts : []).slice(0, 8)) {
  const key = str(f?.key, 40).toLowerCase().replace(/[^a-z0-9_]/g, '_');
  const value = str(f?.value, 80);
  if (!key || !value) continue;
  if (CHILD_NAME.test(key)) continue;
  const isMedicine = isPharmacy && /medic|medik|product|produkt/.test(key);
  if (!isMedicine && hasHealth(value)) { sensitive = true; continue; }
  facts.push({ key, label: str(f.label || key, 60), value });
}

// start_month "2027-01" -> "Januar 2027" (readable in the approval card and on the phone)
const MONTH_NAMES_DE = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
for (const f of facts) {
  const mm = /start_month/.test(f.key) && f.value.match(/^(\d{4})-(\d{1,2})$/);
  if (mm && +mm[2] >= 1 && +mm[2] <= 12) f.value = MONTH_NAMES_DE[+mm[2] - 1] + ' ' + mm[1];
}

const isDoctor = taskType === 'doctor_appointment';
const draft = {
  task_type: taskType,
  user_language: userLang,
  person: { name: str(d.person?.name, 80) },
  organisation: { name: orgName, phone, category: orgCategory, resource_id: resourceId },
  resource_id: resourceId,
  goal_user: goalUser,
  goal_de: goalDe,
  time_windows: windows,
  constraints,
  allowed_facts: facts,
  reason_category: isDoctor && REASONS.includes(d.reason_category) ? d.reason_category : null,
  is_new_patient: isDoctor && typeof d.is_new_patient === 'boolean' ? d.is_new_patient : null,
  has_referral: isDoctor && typeof d.has_referral === 'boolean' ? d.has_referral : null,
  insurance_type: isDoctor && ['gkv','pkv','other'].includes(d.insurance_type) ? d.insurance_type : null,
  insurance_name: isDoctor ? (str(d.insurance_name, 80) || null) : null,
  opening_de: str(d.opening_de, 400),
  opening_user: str(d.opening_user, 400),
  sensitive_removed: sensitive,
  refuse_reason: REFUSE.includes(d.refuse_reason) ? d.refuse_reason : null
};
// Opening (Plan v2 F6): disclosure + the right name. course/kita openings are built deterministically
// from the facts (same purpose clause as workflow 01); other types fall back when the model got the name wrong.
const n = draft.person.name;
const MONTHS_DE = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
const factVal = re => (facts.find(f => re.test(f.key)) || {}).value || '';
const ageM = factVal(/child_age|^age/).toLowerCase().match(/\d+(?:[.,]\d+)?/);
const ageMonths = /monat|month|міс|мес|\bay\b|شهر/u.test(factVal(/child_age|^age/).toLowerCase());
const monthDe = v => { const m = String(v || '').match(/^(\d{4})-(\d{1,2})/); return m && +m[2] >= 1 && +m[2] <= 12 ? MONTHS_DE[+m[2] - 1] + ' ' + m[1] : String(v || '').slice(0, 40); };
const ageN = ageM ? ageM[0].replace('.', ',') : '';
const CLAUSE = {
  course_enquiry: () => 'wollte fragen, ob es in Ihrem Kurs für ' + (ageN ? (ageMonths ? 'Kinder im Alter von ' + ageN + ' Monaten' : ageN + '-Jährige') : 'Kinder') + ' noch einen Platz oder eine Probestunde gibt',
  kita_enquiry: () => 'wollte fragen, ob Sie ab ' + (monthDe(factVal(/start_month|^start/)) || 'dem gewünschten Monat') + ' einen Betreuungsplatz für ' +
    (ageN ? (ageMonths ? 'ein ' + ageN + ' Monate altes Kind' : 'ein ' + ageN + '-jähriges Kind') : (factVal(/birth/) ? 'ein Kind (geboren ' + factVal(/birth/) + ')' : 'ein Kind')) + ' haben und wie man auf die Warteliste kommt'
};
const EXAMPLE_NAME = /Amina Haddad|Maria Haddad/g;
// name unknown (draft not ready yet): a grammatical neutral opening instead of 'für meiner Auftraggeberin'
const baseOpening = n ? 'Guten Tag! Hier ist die KI-Assistentin von ' + n + '. Ich rufe für ' + n + ' an, weil ' + n + ' noch nicht so gut Deutsch spricht'
  : 'Guten Tag! Hier ist eine KI-Assistentin. Ich rufe im Auftrag einer Person an, die noch nicht so gut Deutsch spricht';
if (CLAUSE[taskType]) {
  draft.opening_de = baseOpening + ', und ' + CLAUSE[taskType]() + '.';
} else if (!n || !/KI-Assistentin/.test(draft.opening_de) || !draft.opening_de.includes(n)) {
  draft.opening_de = baseOpening + '.';
} else if (/KI-Assistentin von (HalloTermin|Amina Haddad)/.test(draft.opening_de) && draft.person.name && !/Amina Haddad/.test(draft.person.name)) {
  draft.opening_de = draft.opening_de.replace(/KI-Assistentin von (HalloTermin|Amina Haddad)/, 'KI-Assistentin von ' + draft.person.name);
}
if (draft.person.name && !/Amina Haddad/.test(draft.person.name)) draft.opening_user = draft.opening_user.replace(EXAMPLE_NAME, draft.person.name);
// 'AI' in the user's language on the approval card (the model sometimes copies the German 'KI')
if (userLang === 'ru') draft.opening_user = draft.opening_user.replace(/(?<!\p{L})КИ(?=[-\s])/gu, 'ИИ');
if (userLang === 'uk') draft.opening_user = draft.opening_user.replace(/(?<!\p{L})К[ИІ](?=[-\s])/gu, 'ШІ');
if (userLang === 'en') draft.opening_user = draft.opening_user.replace(/(?<!\p{L})KI(?=[-\s]assistant)/gu, 'AI');
if (userLang === 'tr') draft.opening_user = draft.opening_user.replace(/(?<!\p{L})KI[-\s]?(?=asistan)/gu, 'yapay zekâ ');

// missing[]: keep model questions (max 3); add deterministic essentials the model forgot
const present = {
  'organisation.phone': !!phone, 'person.name': !!draft.person.name, 'goal_user': !!goalUser,
  'reason_category': !!draft.reason_category, 'is_new_patient': draft.is_new_patient !== null,
  'insurance_type': !!draft.insurance_type, 'time_windows': windows.length > 0,
  'constraints.party_size': !!constraints.party_size
};
const hasFact = e => e.slice(5).split('|').some(k => facts.some(f => f.key.includes(k))) || (e === 'fact:medicine' && facts.some(f => /medic|produkt|product/.test(f.key)));
const missingFields = ESSENTIALS[taskType].filter(e => e.startsWith('fact:') ? !hasFact(e) : !present[e]);
// never ask again for what the prefill (or a valid value) already provides
const ORG_Q = /^(organisation|organization|org)(\.|_|$)|phone|telefon|^provider|^practice|^place/i;
let missing = (Array.isArray(d.missing) ? d.missing : [])
  .filter(m => m && str(m.question_user, 300))
  .filter(m => !CHILD_NAME.test(str(m.field, 60)))
  .filter(m => !(ORG_Q.test(str(m.field, 60)) && (/phone|telefon/i.test(str(m.field, 60)) ? !!phone : !!orgName)))
  .map(m => ({ field: str(m.field, 60), question_user: str(m.question_user, 300), options: Array.isArray(m.options) ? m.options.slice(0, 6).map(o => str(o, 60)).filter(Boolean) : [] }));
missing = missing.slice(0, 3);
const essentials_missing = missingFields;

return { json: { ok: true, draft: { ...draft, missing, essentials_missing, ready: missingFields.length === 0 && !draft.refuse_reason } } };
